  `advanced` tinyint(4) NOT NULL DEFAULT 0,
  `team_num` smallint(4) unsigned NOT NULL DEFAULT 0,
  `tournament_team_num` smallint(5) unsigned NOT NULL DEFAULT 0,
  `match_num` smallint(4) unsigned NOT NULL DEFAULT 0,
  `extra_match_num` smallint(5) unsigned NOT NULL DEFAULT 0,
  `match_level` smallint(4) unsigned NOT NULL DEFAULT 0,
  `place_num` smallint(5) unsigned NOT NULL DEFAULT 1,
  `navi_index` int(11) NOT NULL DEFAULT 0,
  `del` tinyint(1) unsigned NOT NULL DEFAULT 0,
  `create_date` datetime NOT NULL,
  `update_date` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;
