DROP TABLE IF EXISTS `entry_field_def`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `entry_field_def` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `series` int(10) unsigned NOT NULL DEFAULT 0,
  `year` int(10) unsigned DEFAULT NULL,
  `field_order` smallint(5) unsigned NOT NULL DEFAULT 0,
  `field` varchar(128) NOT NULL,
  `data` varchar(128) NOT NULL,
  `name` varchar(128) NOT NULL,
  `kind` varchar(128) NOT NULL,
  `placeholder` text NOT NULL,
  `leader` text NOT NULL,
  `tail` text NOT NULL,
  `text_width` smallint(4) NOT NULL DEFAULT 0,
  `select_info` text NOT NULL,
  `span_next` tinyint(1) NOT NULL DEFAULT 0,
  `float_left` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `required` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `excel_out_order` smallint(3) unsigned NOT NULL DEFAULT 0,
  `excel_title1` text DEFAULT NULL,
  `excel_title2` text DEFAULT NULL,
  `excel_title3` text DEFAULT NULL,
  `del` tinyint(3) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=103 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;
