--
-- Table structure for table `kojin_tournament`
--

DROP TABLE IF EXISTS `kojin_tournament`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `kojin_tournament` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `series` smallint(4) unsigned NOT NULL DEFAULT 0,
  `year` int(11) NOT NULL DEFAULT 0,
  `series_mw` varchar(4) NOT NULL DEFAULT 'm',
  `no` tinyint(4) NOT NULL DEFAULT 0,
  `player_num` smallint(4) unsigned NOT NULL DEFAULT 0,
  `tournament_player_num` smallint(4) unsigned NOT NULL DEFAULT 0,
  `match_num` smallint(4) unsigned NOT NULL DEFAULT 0,
  `extra_match_num` smallint(6) unsigned NOT NULL DEFAULT 0,
  `match_level` smallint(4) unsigned NOT NULL DEFAULT 0,
  `place_num` smallint(5) unsigned NOT NULL DEFAULT 1,
  `tournament_name` text NOT NULL,
