DROP TABLE IF EXISTS `kojin_tournament_player`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `kojin_tournament_player` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `tournament` smallint(4) unsigned NOT NULL DEFAULT 0,
  `tournament_player_index` smallint(4) unsigned NOT NULL DEFAULT 0,
  `team` int(10) unsigned NOT NULL DEFAULT 0,
  `player` smallint(4) unsigned NOT NULL DEFAULT 0,
  `relative` smallint(5) unsigned NOT NULL DEFAULT 0,
  `relative_match` smallint(5) unsigned NOT NULL DEFAULT 0,
  `create_date` datetime NOT NULL,
  `update_date` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `del` tinyint(1) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=261 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;
